"""Recipient-bound shared Bot connector consent and operation receipts."""
VERSION=61
REQUIRED_COLUMNS={
 'shared_connector_links':{'link_id','owner_id','issuer','subject','key_fingerprint','server_id','server_revision','credential_ref_sha256','revision','preferences_revision','state'},
 'shared_connector_preferences':{'consent_id','link_id','scope','team_id','publication_id','revision','state'},
 'shared_connector_requests':{'request_id','link_id','authority_id','room_id','agent_id','root_event_id','run_generation','action_id','session_generation','team_id','publication_id','state','consent_id','consent_scope','consent_revision','preference_revision','tool_id','owner_epoch','publication_revision','revocation_epoch','authority_revision'},
 'shared_connector_commands':{'owner_id','issuer','subject','key_fingerprint','operation_id','request_digest','session_generation','team_id','publication_id','state','response'},
}
def upgrade(db):
 db.execute('''CREATE TABLE shared_connector_links (link_id TEXT PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),issuer TEXT NOT NULL,subject TEXT NOT NULL,key_fingerprint TEXT NOT NULL,server_id TEXT NOT NULL REFERENCES mcp_servers(server_id),server_revision INTEGER NOT NULL CHECK(server_revision>0),credential_ref_sha256 TEXT NOT NULL CHECK(length(credential_ref_sha256)=64),revision INTEGER NOT NULL CHECK(revision>0),preferences_revision INTEGER NOT NULL CHECK(preferences_revision>0),state TEXT NOT NULL CHECK(state IN ('active','revoked','uncertain')),UNIQUE(owner_id,server_id))''')
 db.execute('''CREATE TABLE shared_connector_preferences (consent_id TEXT PRIMARY KEY,link_id TEXT NOT NULL REFERENCES shared_connector_links(link_id),scope TEXT NOT NULL CHECK(scope IN ('bot','all')),team_id TEXT NOT NULL,publication_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),state TEXT NOT NULL CHECK(state IN ('active','revoked')),UNIQUE(link_id,scope,team_id,publication_id))''')
 db.execute('''CREATE TABLE shared_connector_requests (request_id TEXT PRIMARY KEY,link_id TEXT NOT NULL REFERENCES shared_connector_links(link_id),authority_id TEXT NOT NULL UNIQUE,room_id INTEGER NOT NULL REFERENCES conversations(id),agent_id INTEGER NOT NULL REFERENCES agents(id),root_event_id TEXT NOT NULL REFERENCES room_events(event_id),run_generation INTEGER NOT NULL CHECK(run_generation>0),action_id TEXT NOT NULL UNIQUE,session_generation TEXT NOT NULL,owner_epoch TEXT NOT NULL,publication_revision INTEGER NOT NULL,revocation_epoch INTEGER NOT NULL,authority_revision TEXT NOT NULL,team_id TEXT NOT NULL,publication_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','allowed','skipped','consumed','revoked','uncertain')),tool_id TEXT NOT NULL,consent_id TEXT,consent_scope TEXT,consent_revision INTEGER NOT NULL DEFAULT 0,preference_revision INTEGER NOT NULL DEFAULT 0,UNIQUE(room_id,root_event_id,action_id))''')
 db.execute('''CREATE TABLE shared_connector_commands (owner_id INTEGER NOT NULL REFERENCES users(id),issuer TEXT NOT NULL,subject TEXT NOT NULL,key_fingerprint TEXT NOT NULL,operation_id TEXT NOT NULL,request_digest TEXT NOT NULL CHECK(length(request_digest)=64),session_generation TEXT NOT NULL,team_id TEXT NOT NULL,publication_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','committed','uncertain')),response TEXT NOT NULL,PRIMARY KEY(owner_id,issuer,subject,operation_id))''')
